void lwcglGLRegisterContext(void*ctx){if(!ctx)return;lock_contexts();for(size_t i=0;i<MAX_CONTEXTS;i++)if(contexts[i].context==ctx){unlock_contexts();return;}for(size_t i=0;i<MAX_CONTEXTS;i++)if(!contexts[i].context){contexts[i].context=ctx;contexts[i].generation=atomic_fetch_add_explicit(&next_generation,1,memory_order_relaxed);break;}unlock_contexts();}
