static void destroy_caps(GLCapabilities*c){lwcglClearError();if(!c)return;if(selected==c){selected=NULL;clear_tables();}free(c->internal);memset(c,0,sizeof*c);free(c);}
static int valid_selected(GLCapabilities*c){if(!c)return 0;void*ctx=glfwGetCurrentContext();uint64_t gen=lwcglGLContextGeneration(ctx);return ctx&&c->context==ctx&&gen&&c->contextGeneration==gen;}
static GLCapabilities*get_caps(void){if(selected&&!valid_selected(selected)){selected=NULL;clear_tables();lwcglSetErrorInternal(LWCGL_ERROR_CONTEXT_MISMATCH,"GL.getCapabilities: selected capabilities do not belong to current context");}return selected;}
static int set_caps(GLCapabilities*c){lwcglClearError();if(!c){selected=NULL;clear_tables();return 0;}if(c->abiVersion!=LWCGL_ABI_VERSION||c->abiSize!=sizeof*c){lwcglSetErrorInternal(LWCGL_ERROR_STATE,"GL.setCapabilities: ABI mismatch");return -1;}if(!valid_selected(c)){lwcglSetErrorInternal(LWCGL_ERROR_CONTEXT_MISMATCH,"GL.setCapabilities: capabilities do not belong to current context");return -1;}selected=c;apply(c);return 0;}
